import { createClient } from "@/lib/supabase/server";
import { ActivityCard, SpaceCard, type ActivityWithSpace } from "@/components/Cards";
import { CATEGORIES } from "@/lib/types";

const str = (v: string | string[] | undefined) => (typeof v === "string" ? v.trim() : "");

export default async function Explore({ searchParams }: PageProps<"/explore">) {
  const sp = await searchParams;
  const city = str(sp.city), category = str(sp.category), age = Number(str(sp.age)) || null;
  const supabase = await createClient();

  let aq = supabase
    .from("activities")
    .select("*, spaces!inner(id, name, city, images, status)")
    .eq("spaces.status", "approved")
    .gte("starts_at", new Date().toISOString())
    .order("starts_at")
    .limit(60);
  if (city) aq = aq.ilike("spaces.city", `%${city}%`);
  if (category) aq = aq.eq("category", category);
  if (age) aq = aq.lte("age_min", age).gte("age_max", age);

  let sq = supabase.from("spaces").select("id, name, city, address, images").eq("status", "approved").limit(30);
  if (city) sq = sq.ilike("city", `%${city}%`);

  const [{ data: activities }, { data: spaces }] = await Promise.all([aq, sq]);

  return (
    <div className="mx-auto max-w-6xl px-4 py-10">
      <h1 className="font-display text-4xl font-extrabold">Explore {city && <span className="text-sky">in {city}</span>}</h1>
      <form className="card mt-4 grid gap-3 p-4 sm:grid-cols-4">
        <input name="city" defaultValue={city} placeholder="City" className="input" />
        <select name="category" defaultValue={category} className="input">
          <option value="">All categories</option>
          {CATEGORIES.map((c) => <option key={c}>{c}</option>)}
        </select>
        <input name="age" type="number" min={3} max={19} defaultValue={age ?? ""} placeholder="Child's age" className="input" />
        <button className="btn-primary">Search</button>
      </form>

      <h2 className="mb-3 mt-8 font-display text-2xl font-bold">Upcoming activities ({activities?.length ?? 0})</h2>
      {activities?.length ? (
        <div className="grid gap-4 md:grid-cols-2">
          {(activities as ActivityWithSpace[]).map((a) => <ActivityCard key={a.id} a={a} />)}
        </div>
      ) : (
        <p className="card p-8 text-center text-ink/60">Nothing matches yet. Try another city or category.</p>
      )}

      {!!spaces?.length && (
        <>
          <h2 className="mb-3 mt-10 font-display text-2xl font-bold">Spaces {city && `in ${city}`}</h2>
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {spaces.map((s) => <SpaceCard key={s.id} space={s} />)}
          </div>
        </>
      )}
    </div>
  );
}
EOF

