"use server";

import { revalidatePath } from "next/cache";
import { createClient } from "@/lib/supabase/server";

export type RegState = { error?: string; ok?: boolean } | undefined;

export async function register(_: RegState, form: FormData): Promise<RegState> {
  const supabase = await createClient();
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) return { error: "Please log in first." };
  const { error } = await supabase.from("registrations").insert({
    activity_id: String(form.get("activity_id")),
    participant_name: String(form.get("participant_name")).trim(),
    participant_age: Number(form.get("participant_age")) || null,
    contact_phone: String(form.get("contact_phone") || "") || null,
    notes: String(form.get("notes") || "") || null,
  });
  if (error) {
    if (error.code === "23505") return { error: "This participant is already registered." };
    return { error: error.message };
  }
  revalidatePath(`/spaces/${form.get("space_id")}`);
  return { ok: true };
}
