-- FitVerse Jr. core schema
-- Roles: super_admin (us), host (lists spaces), user (student / parent / school)

create type public.app_role as enum ('super_admin', 'host', 'user');
create type public.user_kind as enum ('student', 'parent', 'school');
create type public.space_status as enum ('pending', 'approved', 'rejected');

-- ---------------------------------------------------------------- profiles
create table public.profiles (
  id uuid primary key references auth.users on delete cascade,
  email text,
  full_name text,
  role public.app_role not null default 'user',
  user_kind public.user_kind,
  phone text,
  city text,
  created_at timestamptz not null default now()
);

create or replace function public.is_admin()
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.profiles where id = auth.uid() and role = 'super_admin');
$$;

-- New auth user -> profile. Self-signup may only pick host or user; super_admin is granted by SQL.
create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  insert into public.profiles (id, email, full_name, role, user_kind, phone, city)
  values (
    new.id,
    new.email,
    coalesce(new.raw_user_meta_data->>'full_name', new.raw_user_meta_data->>'name'),
    case when new.raw_user_meta_data->>'role' = 'host' then 'host'::public.app_role else 'user'::public.app_role end,
    case when new.raw_user_meta_data->>'user_kind' in ('student', 'parent', 'school')
      then (new.raw_user_meta_data->>'user_kind')::public.user_kind end,
    new.raw_user_meta_data->>'phone',
    new.raw_user_meta_data->>'city'
  );
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

alter table public.profiles enable row level security;

create policy "profiles: read own or admin" on public.profiles
  for select using (id = auth.uid() or public.is_admin());
create policy "profiles: update own or admin" on public.profiles
  for update using (id = auth.uid() or public.is_admin());

-- Users can't change their own role/email; role changes go through set_user_role().
revoke update on public.profiles from authenticated, anon;
grant update (full_name, user_kind, phone, city) on public.profiles to authenticated;

create or replace function public.set_user_role(target uuid, new_role public.app_role)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if not public.is_admin() then raise exception 'only super admins can change roles'; end if;
  update public.profiles set role = new_role where id = target;
end;
$$;

-- ------------------------------------------------------------------ spaces
create table public.spaces (
  id uuid primary key default gen_random_uuid(),
  host_id uuid not null default auth.uid() references public.profiles on delete cascade,
  name text not null,
  description text,
  address text not null,
  city text not null,
  lat double precision,
  lng double precision,
  images text[] not null default '{}',
  amenities text[] not null default '{}',
  contact_phone text,
  status public.space_status not null default 'pending',
  admin_note text,
  created_at timestamptz not null default now()
);
create index on public.spaces (status, city);
create index on public.spaces (host_id);

-- Only admins decide status. Host edits send an approved/rejected space back to review.
create or replace function public.guard_space_status()
returns trigger language plpgsql set search_path = '' as $$
begin
  if not public.is_admin() then
    new.status := 'pending';
    new.admin_note := case when tg_op = 'UPDATE' then old.admin_note end;
    new.host_id := case when tg_op = 'UPDATE' then old.host_id else auth.uid() end;
  end if;
  return new;
end;
$$;

create trigger spaces_guard before insert or update on public.spaces
  for each row execute function public.guard_space_status();

alter table public.spaces enable row level security;

create policy "spaces: public reads approved" on public.spaces
  for select using (status = 'approved' or host_id = auth.uid() or public.is_admin());
create policy "spaces: hosts create" on public.spaces
  for insert with check (
    exists (select 1 from public.profiles where id = auth.uid() and role in ('host', 'super_admin'))
  );
create policy "spaces: owner or admin updates" on public.spaces
  for update using (host_id = auth.uid() or public.is_admin());
create policy "spaces: owner or admin deletes" on public.spaces
  for delete using (host_id = auth.uid() or public.is_admin());

-- -------------------------------------------------------------- activities
create table public.activities (
  id uuid primary key default gen_random_uuid(),
  space_id uuid not null references public.spaces on delete cascade,
  title text not null,
  description text,
  category text not null,
  age_min int not null default 5 check (age_min >= 0),
  age_max int not null default 16 check (age_max >= age_min),
  starts_at timestamptz not null,
  ends_at timestamptz,
  price numeric(10, 2) not null default 0 check (price >= 0),
  capacity int check (capacity > 0),
  created_at timestamptz not null default now()
);
create index on public.activities (space_id, starts_at);

create or replace function public.owns_space(sid uuid)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.spaces where id = sid and host_id = auth.uid());
$$;

alter table public.activities enable row level security;

-- Visible whenever the parent space is visible (spaces RLS applies inside the subquery).
create policy "activities: read with space" on public.activities
  for select using (exists (select 1 from public.spaces s where s.id = space_id));
create policy "activities: owner or admin writes" on public.activities
  for all using (public.owns_space(space_id) or public.is_admin())
  with check (public.owns_space(space_id) or public.is_admin());

-- ----------------------------------------------------------- registrations
create table public.registrations (
  id uuid primary key default gen_random_uuid(),
  activity_id uuid not null references public.activities on delete cascade,
  user_id uuid not null default auth.uid() references public.profiles on delete cascade,
  participant_name text not null,
  participant_age int check (participant_age between 0 and 25),
  contact_phone text,
  notes text,
  status text not null default 'confirmed' check (status in ('confirmed', 'cancelled')),
  created_at timestamptz not null default now(),
  unique (activity_id, user_id, participant_name)
);
create index on public.registrations (user_id);

-- Capacity check. ponytail: count-then-insert can race at the last seat; add a seat counter row lock if events sell out fast.
create or replace function public.check_capacity()
returns trigger language plpgsql security definer set search_path = '' as $$
declare cap int;
begin
  if new.status <> 'confirmed' then return new; end if;
  select capacity into cap from public.activities where id = new.activity_id;
  if cap is not null and (
    select count(*) from public.registrations
    where activity_id = new.activity_id and status = 'confirmed' and id <> new.id
  ) >= cap then
    raise exception 'This activity is full';
  end if;
  return new;
end;
$$;

create trigger registrations_capacity before insert or update on public.registrations
  for each row execute function public.check_capacity();

alter table public.registrations enable row level security;

create policy "registrations: own, host, admin read" on public.registrations
  for select using (
    user_id = auth.uid()
    or public.is_admin()
    or exists (select 1 from public.activities a where a.id = activity_id and public.owns_space(a.space_id))
  );
create policy "registrations: register for approved space" on public.registrations
  for insert with check (
    user_id = auth.uid()
    and exists (
      select 1 from public.activities a join public.spaces s on s.id = a.space_id
      where a.id = activity_id and s.status = 'approved' and a.starts_at > now()
    )
  );
create policy "registrations: own or admin updates" on public.registrations
  for update using (user_id = auth.uid() or public.is_admin());

revoke update on public.registrations from authenticated, anon;
grant update (status) on public.registrations to authenticated;

-- ----------------------------------------------------------------- storage
insert into storage.buckets (id, name, public) values ('space-images', 'space-images', true)
on conflict (id) do nothing;

-- Files live under "<user id>/..." so each host only touches their own folder.
create policy "space-images: upload own folder" on storage.objects
  for insert to authenticated
  with check (bucket_id = 'space-images' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "space-images: delete own folder" on storage.objects
  for delete to authenticated
  using (bucket_id = 'space-images' and (storage.foldername(name))[1] = auth.uid()::text);

