            <div className="flex flex-wrap gap-2">
              {space.amenities.map((a) => <span key={a} className="chip bg-mint/15 text-sm">✓ {a}</span>)}
            </div>
          )}

          <h2 className="font-display text-2xl font-bold">Upcoming activities</h2>
          {activities?.length ? (
            <div className="space-y-4">
              {activities.map((a) => {
                const left = a.capacity ? a.capacity - (taken.get(a.id) ?? 0) : null;
                return (
                  <div key={a.id} id={a.id} className="card scroll-mt-24 space-y-3 p-5">
                    <div className="flex flex-wrap items-start justify-between gap-2">
                      <div>
                        <div className="flex flex-wrap gap-1.5">
                          <span className="chip bg-sky/15">{a.category}</span>
                          <span className="chip bg-ink/5">Ages {a.age_min}–{a.age_max}</span>
                          {left !== null && <span className={`chip ${left > 0 ? "bg-mint/15" : "bg-coral/15"}`}>{left > 0 ? `${left} spots left` : "Full"}</span>}
                        </div>
                        <h3 className="mt-1 font-display text-xl font-bold">{a.title}</h3>
                        <p className="text-sm font-bold text-ink/60">🗓️ {fmtDate(a.starts_at)}{a.ends_at && ` – ${fmtDate(a.ends_at)}`}</p>
                      </div>
                      <span className="font-display text-2xl font-extrabold text-mint">{fmtPrice(a.price)}</span>
                    </div>
                    {a.description && <p className="text-ink/70">{a.description}</p>}
                    {space.status === "approved" && left !== 0 &&
                      (user ? <RegisterForm activityId={a.id} spaceId={space.id} /> : (
                        <Link href={`/login?next=/spaces/${space.id}`} className="btn-primary">Log in to register</Link>
                      ))}
                  </div>
                );
              })}
            </div>
          ) : (
            <p className="card p-6 text-ink/60">No upcoming activities right now.</p>
          )}
        </div>

        <aside className="space-y-4">
          <div className="card overflow-hidden">
            <iframe title="Map" src={mapEmbed(space)} className="h-72 w-full border-0" loading="lazy" referrerPolicy="no-referrer-when-downgrade" />
            <div className="p-4">
              <a
                href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(space.lat != null && space.lng != null ? `${space.lat},${space.lng}` : `${space.address}, ${space.city}`)}`}
                target="_blank"
                rel="noreferrer"
                className="btn-ghost w-full"
              >
                Open in Google Maps ↗
              </a>
            </div>
          </div>
          {space.contact_phone && (
            <div className="card p-4">
              <div className="label">Contact</div>
              <a href={`tel:${space.contact_phone}`} className="font-bold text-sky">{space.contact_phone}</a>
            </div>
          )}
        </aside>
      </div>
    </div>
  );
}
