"use server";

import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { requireRole } from "@/lib/auth";

export type FormState = { error?: string; ok?: boolean } | undefined;

const text = (f: FormData, k: string) => String(f.get(k) ?? "").trim() || null;
const num = (f: FormData, k: string) => (text(f, k) === null ? null : Number(f.get(k)));

export async function saveSpace(_: FormState, form: FormData): Promise<FormState> {
  const { supabase } = await requireRole("host", "super_admin");
  const id = text(form, "id");
  const row = {
    name: text(form, "name"),
    description: text(form, "description"),
    address: text(form, "address"),
    city: text(form, "city"),
    lat: num(form, "lat"),
    lng: num(form, "lng"),
    contact_phone: text(form, "contact_phone"),
    amenities: (text(form, "amenities") ?? "").split(",").map((s) => s.trim()).filter(Boolean),
    images: form.getAll("images").map(String),
  };
  if (!row.name || !row.address || !row.city) return { error: "Name, address and city are required." };

  const { data, error } = id
    ? await supabase.from("spaces").update(row).eq("id", id).select("id").single()
    : await supabase.from("spaces").insert(row).select("id").single();
  if (error) return { error: error.message };
  revalidatePath("/host");
  redirect(`/host/spaces/${data.id}`);
}

export async function deleteSpace(form: FormData) {
  const { supabase } = await requireRole("host", "super_admin");
  await supabase.from("spaces").delete().eq("id", String(form.get("id")));
  revalidatePath("/host");
  redirect("/host");
}

export async function saveActivity(_: FormState, form: FormData): Promise<FormState> {
  const { supabase } = await requireRole("host", "super_admin");
  const spaceId = String(form.get("space_id"));
  const startsAt = text(form, "starts_at"), endsAt = text(form, "ends_at");
  const tz = Number(form.get("tz_offset") ?? 0); // browser offset so local datetime-local input becomes the right instant
  const toIso = (v: string) => new Date(new Date(v + "Z").getTime() + tz * 60_000).toISOString();
  if (!text(form, "title") || !startsAt) return { error: "Title and start time are required." };

  const { error } = await supabase.from("activities").insert({
    space_id: spaceId,
    title: text(form, "title"),
    description: text(form, "description"),
    category: text(form, "category"),
    age_min: num(form, "age_min") ?? 5,
    age_max: num(form, "age_max") ?? 16,
    starts_at: toIso(startsAt),
    ends_at: endsAt ? toIso(endsAt) : null,
    price: num(form, "price") ?? 0,
    capacity: num(form, "capacity"),
  });
  if (error) return { error: error.message };
  revalidatePath(`/host/spaces/${spaceId}`);
  return { ok: true };
}

export async function deleteActivity(form: FormData) {
  const { supabase } = await requireRole("host", "super_admin");
  await supabase.from("activities").delete().eq("id", String(form.get("id")));
  revalidatePath(`/host/spaces/${form.get("space_id")}`);
}
