"use client";

import { useActionState, useState } from "react";
import { createClient } from "@/lib/supabase/client";
import { saveSpace, type FormState } from "@/app/host/actions";
import type { Space } from "@/lib/types";

// Pulls coordinates out of a pasted Google Maps URL (".../@12.97,77.59,15z" or "?q=12.97,77.59").
const coordsFrom = (url: string) => url.match(/[@=](-?\d+\.\d+),\s*(-?\d+\.\d+)/)?.slice(1, 3);

export default function SpaceForm({ space }: { space?: Space }) {
  const [images, setImages] = useState<string[]>(space?.images ?? []);
  const [lat, setLat] = useState(space?.lat?.toString() ?? "");
  const [lng, setLng] = useState(space?.lng?.toString() ?? "");

  const [state, action, pending] = useActionState(async (prev: FormState, form: FormData) => {
    const files = (form.getAll("files") as File[]).filter((f) => f.size > 0);
    form.delete("files");
    if (files.length) {
      const supabase = createClient();
      const { data: { user } } = await supabase.auth.getUser();
      for (const file of files) {
        const path = `${user!.id}/${crypto.randomUUID()}-${file.name.replace(/[^\w.-]/g, "_")}`;
        const { error } = await supabase.storage.from("space-images").upload(path, file);
        if (error) return { error: `Upload failed: ${error.message}` };
        form.append("images", supabase.storage.from("space-images").getPublicUrl(path).data.publicUrl);
      }
    }
    return saveSpace(prev, form);
  }, undefined);

  return (
    <form action={action} className="card space-y-5 p-6">
      {space && <input type="hidden" name="id" value={space.id} />}
      {images.map((src) => <input key={src} type="hidden" name="images" value={src} />)}

      <div><label className="label">Space name *</label><input name="name" required defaultValue={space?.name} className="input" placeholder="e.g. Sunrise Sports Arena" /></div>
      <div><label className="label">Description</label><textarea name="description" rows={4} defaultValue={space?.description ?? ""} className="input" placeholder="What makes your space special for kids?" /></div>

      <div className="grid gap-4 sm:grid-cols-2">
        <div><label className="label">Address *</label><input name="address" required defaultValue={space?.address} className="input" /></div>
        <div><label className="label">City *</label><input name="city" required defaultValue={space?.city} className="input" /></div>
      </div>

      <div className="rounded-2xl bg-sky/5 p-4">
        <label className="label">Google Maps link (optional — fills coordinates)</label>
        <input
          className="input"
          placeholder="Paste a google.com/maps/... link"
          onChange={(e) => {
            const c = coordsFrom(e.target.value);
            if (c) { setLat(c[0]); setLng(c[1]); }
          }}
        />
        <div className="mt-3 grid grid-cols-2 gap-3">
          <input name="lat" value={lat} onChange={(e) => setLat(e.target.value)} type="number" step="any" placeholder="Latitude" className="input" />
          <input name="lng" value={lng} onChange={(e) => setLng(e.target.value)} type="number" step="any" placeholder="Longitude" className="input" />
        </div>
        <p className="mt-2 text-xs text-ink/50">No coordinates? We&apos;ll place the map pin using the address.</p>
      </div>

      <div className="grid gap-4 sm:grid-cols-2">
        <div><label className="label">Contact phone</label><input name="contact_phone" type="tel" defaultValue={space?.contact_phone ?? ""} className="input" /></div>
        <div><label className="label">Amenities (comma separated)</label><input name="amenities" defaultValue={space?.amenities.join(", ")} className="input" placeholder="Parking, Washrooms, Water, First aid" /></div>
      </div>

      <div>
        <label className="label">Photos</label>
        {!!images.length && (
          <div className="mb-3 flex flex-wrap gap-3">
            {images.map((src) => (
              <div key={src} className="relative">
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img src={src} alt="" className="h-24 w-32 rounded-xl object-cover" />
                <button type="button" onClick={() => setImages(images.filter((i) => i !== src))} className="absolute -right-2 -top-2 h-6 w-6 rounded-full bg-coral text-xs font-bold text-white" aria-label="Remove photo">×</button>
              </div>
            ))}
          </div>
        )}
        <input name="files" type="file" accept="image/*" multiple className="input" />
      </div>

      {space?.status === "approved" && <p className="rounded-2xl bg-sun/30 px-4 py-2 text-sm font-bold">Heads up: saving changes sends this space back for admin review.</p>}
      {state?.error && <p className="rounded-2xl bg-coral/10 px-4 py-2 text-sm font-bold text-coral">{state.error}</p>}
      <button className="btn-primary" disabled={pending}>{pending ? "Saving…" : space ? "Save changes" : "Submit for review"}</button>
    </form>
  );
}
