        <h1 className="font-display text-4xl font-extrabold">{space.name}</h1>
        <StatusChip status={space.status} />
        <Link href={`/spaces/${space.id}`} className="btn-ghost ml-auto !py-2 text-sm">View public page ↗</Link>
