          <h2 className="font-display text-2xl font-bold">Activities</h2>
          <ActivityForm spaceId={space.id} />
          {activities?.map((a) => {
            const regs = a.registrations.filter((r) => r.status === "confirmed");
            return (
              <div key={a.id} className="card space-y-3 p-5">
                <div className="flex items-start justify-between gap-2">
                  <div>
                    <h3 className="font-display text-lg font-bold">{a.title}</h3>
