                  </div>
                  <form action={deleteActivity}>
                    <input type="hidden" name="id" value={a.id} />
                    <input type="hidden" name="space_id" value={space.id} />
                    <button className="text-sm font-bold text-coral">Delete</button>
                  </form>
                </div>
                <details>
                  <summary className="cursor-pointer text-sm font-bold">
                    {regs.length}{a.capacity ? ` / ${a.capacity}` : ""} registered
                  </summary>
                  {regs.length ? (
                    <table className="mt-2 w-full text-left text-sm">
                      <thead className="text-ink/50"><tr><th>Name</th><th>Age</th><th>Phone</th><th>Notes</th></tr></thead>
                      <tbody>
                        {regs.map((r) => (
                          <tr key={r.id} className="border-t border-ink/5">
                            <td className="py-1">{r.participant_name}</td><td>{r.participant_age ?? "–"}</td>
                            <td>{r.contact_phone ?? "–"}</td><td>{r.notes ?? ""}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  ) : <p className="mt-2 text-sm text-ink/50">No registrations yet.</p>}
                </details>
              </div>
            );
          })}
        </section>

        <section className="space-y-4">
          <h2 className="font-display text-2xl font-bold">Space details</h2>
          <SpaceForm space={space} />
          <form action={deleteSpace} className="text-right">
            <input type="hidden" name="id" value={space.id} />
            <button className="text-sm font-bold text-coral">Delete this space</button>
          </form>
        </section>
      </div>
    </div>
  );
}
