import Link from "next/link";
import { revalidatePath } from "next/cache";
import { requireRole } from "@/lib/auth";
import { fmtDate, fmtPrice } from "@/lib/format";
import type { Activity, Registration, Space } from "@/lib/types";

type Row = Registration & { activities: Activity & { spaces: Pick<Space, "id" | "name" | "city"> } };

async function cancel(form: FormData) {
  "use server";
  const { supabase } = await requireRole();
  await supabase.from("registrations").update({ status: "cancelled" }).eq("id", String(form.get("id")));
  revalidatePath("/me");
}

export default async function MyBookings() {
  const { supabase, profile } = await requireRole();
  const { data } = await supabase
    .from("registrations")
    .select("*, activities(*, spaces(id, name, city))")
    .eq("user_id", profile.id)
    .order("created_at", { ascending: false })
    .returns<Row[]>();
  const now = new Date().toISOString();
  const upcoming = data?.filter((r) => r.activities.starts_at >= now) ?? [];
  const past = data?.filter((r) => r.activities.starts_at < now) ?? [];

  const list = (rows: Row[], canCancel: boolean) =>
    rows.map((r) => (
      <div key={r.id} className={`card flex flex-wrap items-center justify-between gap-3 p-5 ${r.status === "cancelled" ? "opacity-50" : ""}`}>
        <div>
          <Link href={`/spaces/${r.activities.spaces.id}#${r.activity_id}`} className="font-display text-lg font-bold hover:text-sky">{r.activities.title}</Link>
          <p className="text-sm text-ink/60">
            📍 {r.activities.spaces.name}, {r.activities.spaces.city} · 🗓️ {fmtDate(r.activities.starts_at)} · {fmtPrice(r.activities.price)}
          </p>
          <p className="text-sm">For <b>{r.participant_name}</b>{r.participant_age && `, ${r.participant_age} yrs`}</p>
        </div>
        {r.status === "cancelled" ? <span className="chip bg-ink/5">Cancelled</span> : canCancel && (
          <form action={cancel}><input type="hidden" name="id" value={r.id} /><button className="btn-ghost !py-2 text-sm">Cancel</button></form>
        )}
      </div>
    ));

  return (
    <div className="mx-auto max-w-4xl px-4 py-10">
      <h1 className="font-display text-4xl font-extrabold">My bookings 🎒</h1>
      <p className="mb-6 text-ink/60">Signed in as {profile.full_name || profile.email}{profile.user_kind && ` · ${profile.user_kind}`}</p>
      <h2 className="mb-3 font-display text-2xl font-bold">Upcoming</h2>
      <div className="space-y-3">
        {upcoming.length ? list(upcoming, true) : (
          <p className="card p-8 text-center text-ink/60">No upcoming bookings. <Link href="/explore" className="font-bold text-sky">Find something fun →</Link></p>
        )}
      </div>
      {!!past.length && (<><h2 className="mb-3 mt-10 font-display text-2xl font-bold">Past</h2><div className="space-y-3">{list(past, false)}</div></>)}
    </div>
  );
}
