import Link from "next/link";
import { requireRole } from "@/lib/auth";
import StatusChip from "@/components/StatusChip";
import { reviewSpace, setRole } from "@/app/admin/actions";
import { fmtDate } from "@/lib/format";
import type { Activity, Profile, Registration, Space } from "@/lib/types";

const TABS = ["overview", "spaces", "users", "bookings"] as const;

export default async function Admin({ searchParams }: PageProps<"/admin">) {
  const { supabase, profile: me } = await requireRole("super_admin");
  const tabParam = (await searchParams).tab;
  const tab = TABS.find((t) => t === tabParam) ?? "overview";

  const [{ data: spaces }, { data: users }, { data: regs }, { count: upcoming }] = await Promise.all([
    supabase.from("spaces").select("*, profiles(full_name, email)").order("created_at", { ascending: false })
      .returns<(Space & { profiles: Pick<Profile, "full_name" | "email"> })[]>(),
    supabase.from("profiles").select("*").order("created_at", { ascending: false }).returns<Profile[]>(),
    supabase.from("registrations").select("*, activities(title, starts_at, spaces(name, city))").order("created_at", { ascending: false }).limit(200)
      .returns<(Registration & { activities: Pick<Activity, "title" | "starts_at"> & { spaces: Pick<Space, "name" | "city"> } })[]>(),
    supabase.from("activities").select("*", { count: "exact", head: true }).gte("starts_at", new Date().toISOString()),
  ]);
  const pending = spaces?.filter((s) => s.status === "pending") ?? [];
  const count = <T,>(xs: T[] | null, f: (x: T) => boolean) => xs?.filter(f).length ?? 0;

  const stats = [
    { label: "Pending review", value: pending.length, tint: "bg-sun/40" },
    { label: "Live spaces", value: count(spaces, (s) => s.status === "approved"), tint: "bg-mint/20" },
    { label: "Upcoming activities", value: upcoming ?? 0, tint: "bg-sky/20" },
    { label: "Confirmed bookings", value: count(regs, (r) => r.status === "confirmed"), tint: "bg-coral/15" },
    { label: "Hosts", value: count(users, (u) => u.role === "host"), tint: "bg-grape/15" },
    { label: "Users", value: count(users, (u) => u.role === "user"), tint: "bg-ink/5" },
  ];

  const ReviewForm = ({ s }: { s: Space }) => (
    <form action={reviewSpace} className="flex flex-wrap items-center gap-2">
      <input type="hidden" name="id" value={s.id} />
      <input name="admin_note" defaultValue={s.admin_note ?? ""} placeholder="Note to host (optional)" className="input !w-56 !py-1.5 text-sm" />
      {s.status !== "approved" && <button name="status" value="approved" className="btn !py-1.5 bg-mint text-sm text-white">Approve</button>}
      {s.status !== "rejected" && <button name="status" value="rejected" className="btn !py-1.5 bg-coral/15 text-sm text-coral">Reject</button>}
    </form>
  );

  const SpaceRow = ({ s }: { s: (typeof pending)[number] }) => (
    <div className="card flex flex-wrap items-center justify-between gap-3 p-4">
      <div>
        <div className="flex items-center gap-2">
          <Link href={`/spaces/${s.id}`} className="font-display text-lg font-bold hover:text-sky">{s.name}</Link>
          <StatusChip status={s.status} />
        </div>
        <p className="text-sm text-ink/60">📍 {s.address}, {s.city} · Host: {s.profiles?.full_name || s.profiles?.email} · {s.images.length} photos</p>
      </div>
      <ReviewForm s={s} />
    </div>
  );

  return (
    <div className="mx-auto max-w-6xl px-4 py-10">
      <h1 className="font-display text-4xl font-extrabold">Mission control 🚀</h1>
      <nav className="my-6 flex gap-2">
        {TABS.map((t) => (
          <Link key={t} href={`/admin?tab=${t}`} className={`chip px-4 py-2 text-sm capitalize ${t === tab ? "bg-ink text-white" : "bg-white"}`}>{t}</Link>
        ))}
      </nav>

      {tab === "overview" && (
        <>
          <div className="grid grid-cols-2 gap-4 md:grid-cols-3">
            {stats.map((s) => (
              <div key={s.label} className={`card p-5 ${s.tint}`}>
                <div className="font-display text-4xl font-extrabold">{s.value}</div>
                <div className="text-sm font-bold text-ink/60">{s.label}</div>
              </div>
            ))}
          </div>
          <h2 className="mb-3 mt-8 font-display text-2xl font-bold">Waiting for review</h2>
          <div className="space-y-3">
            {pending.length ? pending.map((s) => <SpaceRow key={s.id} s={s} />) : <p className="card p-6 text-ink/60">All caught up ✨</p>}
          </div>
        </>
      )}

      {tab === "spaces" && <div className="space-y-3">{spaces?.map((s) => <SpaceRow key={s.id} s={s} />)}</div>}

      {tab === "users" && (
        <div className="card overflow-x-auto p-4">
          <table className="w-full text-left text-sm">
            <thead className="text-ink/50"><tr><th className="py-2">Name</th><th>Email</th><th>Type</th><th>City</th><th>Joined</th><th>Role</th></tr></thead>
            <tbody>
              {users?.map((u) => (
                <tr key={u.id} className="border-t border-ink/5">
                  <td className="py-2 font-bold">{u.full_name || "—"}</td><td>{u.email}</td><td className="capitalize">{u.user_kind ?? "—"}</td>
                  <td>{u.city || "—"}</td><td>{new Date(u.created_at).toLocaleDateString("en-IN")}</td>
                  <td>
                    {u.id === me.id ? <span className="chip bg-ink text-white">super_admin (you)</span> : (
                      <form action={setRole} className="flex gap-1">
                        <input type="hidden" name="id" value={u.id} />
                        <select name="role" defaultValue={u.role} className="input !w-auto !py-1 text-sm">
                          <option value="user">user</option><option value="host">host</option><option value="super_admin">super_admin</option>
                        </select>
                        <button className="btn-ghost !px-3 !py-1 text-sm">Save</button>
                      </form>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {tab === "bookings" && (
        <div className="card overflow-x-auto p-4">
          <table className="w-full text-left text-sm">
            <thead className="text-ink/50"><tr><th className="py-2">Participant</th><th>Age</th><th>Activity</th><th>Space</th><th>When</th><th>Status</th></tr></thead>
            <tbody>
              {regs?.map((r) => (
                <tr key={r.id} className="border-t border-ink/5">
                  <td className="py-2 font-bold">{r.participant_name}</td><td>{r.participant_age ?? "—"}</td><td>{r.activities.title}</td>
                  <td>{r.activities.spaces.name}, {r.activities.spaces.city}</td><td>{fmtDate(r.activities.starts_at)}</td>
                  <td className="capitalize">{r.status}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}
