      {tab === "users" && (
        <div className="card overflow-x-auto p-4">
          <table className="w-full text-left text-sm">
            <thead className="text-ink/50"><tr><th className="py-2">Name</th><th>Email</th><th>Type</th><th>City</th><th>Joined</th><th>Role</th></tr></thead>
            <tbody>
              {users?.map((u) => (
                <tr key={u.id} className="border-t border-ink/5">
                  <td className="py-2 font-bold">{u.full_name || "—"}</td><td>{u.email}</td><td className="capitalize">{u.user_kind ?? "—"}</td>
                  <td>{u.city || "—"}</td><td>{new Date(u.created_at).toLocaleDateString("en-IN")}</td>
                  <td>
                    {u.id === me.id ? <span className="chip bg-ink text-white">super_admin (you)</span> : (
                      <form action={setRole} className="flex gap-1">
                        <input type="hidden" name="id" value={u.id} />
                        <select name="role" defaultValue={u.role} className="input !w-auto !py-1 text-sm">
                          <option value="user">user</option><option value="host">host</option><option value="super_admin">super_admin</option>
                        </select>
                        <button className="btn-ghost !px-3 !py-1 text-sm">Save</button>
                      </form>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {tab === "bookings" && (
        <div className="card overflow-x-auto p-4">
          <table className="w-full text-left text-sm">
            <thead className="text-ink/50"><tr><th className="py-2">Participant</th><th>Age</th><th>Activity</th><th>Space</th><th>When</th><th>Status</th></tr></thead>
            <tbody>
