  begin insert into public.registrations (activity_id, participant_name) select id,'Kid B' from public.activities; raise exception 'over capacity';
  exception when raise_exception then if sqlerrm <> 'This activity is full' then raise; end if; end;
end $$;
do $$ begin assert (select taken from public.seats_taken((select id from public.spaces)))=1; end $$;
