do $$ begin assert (select count(*) from public.registrations)=1, 'host cannot see regs'; end $$;
update public.spaces set name='Arena 2';
do $$ begin assert (select status from public.spaces)='pending', 'edit should re-queue'; assert (select admin_note from public.spaces)='nice'; end $$;

-- anon
reset request.jwt.claim.sub; set role anon;
do $$ begin assert (select count(*) from public.registrations)=0; assert (select count(*) from public.profiles)=0; end $$;
\echo ALL_RLS_TESTS_PASSED
